#include <Servo.h>

Servo feederServo;

const int servoPin = 9;
const int buttonPin = 2;

bool lastButtonState = HIGH;

void setup() {
  feederServo.attach(servoPin);
  feederServo.write(0);

  pinMode(buttonPin, INPUT_PULLUP);

  Serial.begin(9600);
  Serial.println("Automatic Pet Feeder Ready");
}

void loop() {
  bool buttonState = digitalRead(buttonPin);

  // Detect button press
  if (lastButtonState == HIGH && buttonState == LOW) {
    Serial.println("Dispensing food...");

    // Open the food dispenser
    feederServo.write(90);
    delay(2000);

    // Close the food dispenser
    feederServo.write(0);

    Serial.println("Feeding complete.");

    // Small delay to prevent accidental repeated feeding
    delay(500);
  }

  lastButtonState = buttonState;
}

#define RED_LED    D5
#define YELLOW_LED D6
#define GREEN_LED  D7
#define BLUE_LED   D3

const int leds[] = {
  RED_LED,
  YELLOW_LED,
  GREEN_LED,
  BLUE_LED
};

const int LED_COUNT = 4;

// ==========================================
// 13 RUNNING SPEED STAGES
// ==========================================

const unsigned long SPEED_1  = 10;     // 0-3 sec
const unsigned long SPEED_2  = 20;     // 3-6 sec
const unsigned long SPEED_3  = 40;     // 6-9 sec
const unsigned long SPEED_4  = 50;     // 9-12 sec
const unsigned long SPEED_5  = 80;     // 12-15 sec
const unsigned long SPEED_6  = 100;    // 15-18 sec
const unsigned long SPEED_7  = 200;    // 18-21 sec
const unsigned long SPEED_8  = 300;    // 21-23 sec
const unsigned long SPEED_9  = 500;    // 23-25 sec
const unsigned long SPEED_10 = 700;    // 25-27 sec
const unsigned long SPEED_11 = 900;    // 27-28 sec
const unsigned long SPEED_12 = 1200;   // 28-29 sec
const unsigned long SPEED_13 = 1500;   // 29-30 sec

// ==========================================
// JACKPOT BLINK
// 5 BLINKS = 5 SECONDS
// ==========================================

const int BLINK_COUNT = 5;
const unsigned long BLINK_DELAY = 500;

// ==========================================
// SETUP
// ==========================================

void setup() {
  pinMode(RED_LED, OUTPUT);
  pinMode(YELLOW_LED, OUTPUT);
  pinMode(GREEN_LED, OUTPUT);
  pinMode(BLUE_LED, OUTPUT);

  allOff();

  randomSeed(analogRead(A0));
}

// ==========================================
// MAIN LOOP
// ==========================================

void loop() {

  // Random starting LED
  int currentLED = random(0, LED_COUNT);

  unsigned long runStart = millis();

  // ========================================
  // 30 SECOND RUNNING LIGHT
  // ========================================

  while (millis() - runStart < 30000UL) {

    unsigned long elapsed = millis() - runStart;
    unsigned long speedDelay;

    if (elapsed < 3000UL) {
      speedDelay = SPEED_1;
    } else if (elapsed < 6000UL) {
      speedDelay = SPEED_2;
    } else if (elapsed < 9000UL) {
      speedDelay = SPEED_3;
    } else if (elapsed < 12000UL) {
      speedDelay = SPEED_4;
    } else if (elapsed < 15000UL) {
      speedDelay = SPEED_5;
    } else if (elapsed < 18000UL) {
      speedDelay = SPEED_6;
    } else if (elapsed < 21000UL) {
      speedDelay = SPEED_7;
    } else if (elapsed < 23000UL) {
      speedDelay = SPEED_8;
    } else if (elapsed < 25000UL) {
      speedDelay = SPEED_9;
    } else if (elapsed < 27000UL) {
      speedDelay = SPEED_10;
    } else if (elapsed < 28000UL) {
      speedDelay = SPEED_11;
    } else if (elapsed < 29000UL) {
      speedDelay = SPEED_12;
    } else {
      speedDelay = SPEED_13;
    }

    allOff();

    digitalWrite(leds[currentLED], HIGH);

    delay(speedDelay);

    currentLED++;

    if (currentLED >= LED_COUNT) {
      currentLED = 0;
    }
  }

  // ========================================
  // JACKPOT
  // ========================================

  int jackpotLED = currentLED;

  allOff();

  // ========================================
  // BLINK JACKPOT 5 TIMES
  // ========================================

  for (int i = 0; i < BLINK_COUNT; i++) {

    digitalWrite(leds[jackpotLED], HIGH);
    delay(BLINK_DELAY);

    digitalWrite(leds[jackpotLED], LOW);
    delay(BLINK_DELAY);
  }

  // ========================================
  // RESET
  // ========================================

  allOff();

  delay(200);
}

// ==========================================
// TURN OFF ALL LEDs
// ==========================================

void allOff() {
  digitalWrite(RED_LED, LOW);
  digitalWrite(YELLOW_LED, LOW);
  digitalWrite(GREEN_LED, LOW);
  digitalWrite(BLUE_LED, LOW);
}

